effect.shader:
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

void main() {
    // Ande para cima varrendo até achar o primeiro píxel ABAIXO do limiar — esse é o que fica neste ponto.
    vec2 uv = acScreenNorm;
    vec4 cor = texture(inputImg, uv);
    float l = dot(cor.rgb, LUMA);
    if (l < threshold) { fragColor = cor; return; }

    float passo = acTexelSize.y;
    float dir = sign(downward);
    if (dir == 0.0) dir = 1.0;
    float andar = 0.0;
    vec4 melhor = cor;
    for (int i = 1; i <= 128; i++) {
        float t = float(i) * passo * 2.0;
        if (t > maxLen) break;
        vec2 u = uv + vec2(0.0, dir * t);
        if (u.y < 0.0 || u.y > 1.0) break;
        vec4 c = texture(inputImg, u);
        float ll = dot(c.rgb, LUMA);
        if (ll < threshold) break;
        melhor = c;
        andar = t;
    }
    // Interpola para suavizar a borda
    float k = smoothstep(0.0, maxLen * 0.1, andar);
    fragColor = mix(cor, melhor, k * abs(downward));
}
